function encode(command) {
  var line;
  if (Array.isArray(command)) {
    if (command.length !== 2 || typeof command[0] !== 'number' || typeof command[1] !== 'number' || !isFinite(command[0]) || !isFinite(command[1])) {
      throw new Error('invalid xy command');
    }
    if (Math.abs(command[0]) > 0.1 || Math.abs(command[1]) > 0.1) {
      throw new Error('xy out of range');
    }
    line = JSON.stringify({op: 'step', channels: [command[0], command[1]]});
  } else if (command && typeof command === 'object' && command.op === 'lift') {
    if (command.position !== 'up' && command.position !== 'down') {
      throw new Error('invalid lift position');
    }
    line = JSON.stringify({op: 'lift', position: command.position});
  } else if (command && typeof command === 'object' && command.op === 'grip') {
    if (command.state !== 'open' && command.state !== 'closed') {
      throw new Error('invalid grip state');
    }
    line = JSON.stringify({op: 'grip', state: command.state});
  } else {
    throw new Error('unsupported command');
  }
  return line + '\n';
}

function decode(rawReply) {
  if (typeof rawReply !== 'string') {
    throw new Error('malformed reply: not a string');
  }
  var text = rawReply;
  if (text.length > 0 && text.charAt(text.length - 1) === '\n') {
    text = text.slice(0, -1);
  }
  if (text.length === 0 || text.indexOf('\n') >= 0 || text.indexOf('\r') >= 0) {
    throw new Error('malformed reply: expected exactly one line');
  }
  var reply;
  try {
    reply = JSON.parse(text);
  } catch (e) {
    throw new Error('malformed reply: invalid JSON');
  }
  if (!reply || typeof reply !== 'object' || Array.isArray(reply)) {
    throw new Error('malformed reply: not an object');
  }
  if (reply.ok !== true) {
    throw new Error('device error: ' + (reply.error !== undefined ? String(reply.error) : 'ok false'));
  }
  if (reply.accepted === undefined || reply.accepted === null) {
    throw new Error('malformed reply: missing accepted');
  }
  var acc = reply.accepted;
  if (Array.isArray(acc)) {
    if (acc.length !== 2 || typeof acc[0] !== 'number' || typeof acc[1] !== 'number' || !isFinite(acc[0]) || !isFinite(acc[1])) {
      throw new Error('malformed reply: invalid accepted xy');
    }
  } else if (typeof acc === 'object') {
    if (acc.op !== 'lift' && acc.op !== 'grip') {
      throw new Error('malformed reply: invalid accepted op');
    }
    if (acc.op === 'lift' && acc.position !== 'up' && acc.position !== 'down') {
      throw new Error('malformed reply: invalid lift position');
    }
    if (acc.op === 'grip' && acc.state !== 'open' && acc.state !== 'closed') {
      throw new Error('malformed reply: invalid grip state');
    }
  } else {
    throw new Error('malformed reply: invalid accepted');
  }
  if (reply.limited !== undefined && typeof reply.limited !== 'boolean') {
    throw new Error('malformed reply: invalid limited');
  }
  return {applied: acc, limited: reply.limited === true};
}

