  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);

  if (state.maxActions !== undefined && state.maxActions !== null && state.step >= state.maxActions) {
    return {action: 'stop', reason: 'action budget reached'};
  }
  if (err <= tol) {
    return {action: 'verify'};
  }

  var h = state.history || [];
  var n = h.length;
  var probes = [[lim, 0], [0, lim], [-lim, 0], [0, -lim]];
  var cyc = probes[n % 4];

  // Weighted recency fit of delta = J * applied using all valid samples (applied is the true motion).
  var start = Math.max(0, n - 40);
  var S00 = 0, S01 = 0, S11 = 0;
  var D00 = 0, D01 = 0, D10 = 0, D11 = 0;
  var cnt = 0;
  for (var i = start; i < n; i++) {
    var s = h[i];
    if (!s || !s.applied || !s.delta) continue;
    var a = s.applied, d = s.delta;
    if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    var w = Math.pow(0.92, n - 1 - i);
    S00 += w * a[0] * a[0];
    S01 += w * a[0] * a[1];
    S11 += w * a[1] * a[1];
    D00 += w * d[0] * a[0];
    D01 += w * d[0] * a[1];
    D10 += w * d[1] * a[0];
    D11 += w * d[1] * a[1];
    cnt++;
  }
  if (cnt < 2) {
    return {action: 'move', u: [cyc[0], cyc[1]]};
  }
  var lam = 1e-7;
