  var J00 = D00 * I00 + D01 * I10;
  var J01 = D00 * I01 + D01 * I11;
  var J10 = D10 * I00 + D11 * I10;
  var J11 = D10 * I01 + D11 * I11;
  if (!isFinite(J00) || !isFinite(J01) || !isFinite(J10) || !isFinite(J11)) {
