  }
  var detJ = J00 * J11 - J01 * J10;
  var normJ2 = J00 * J00 + J01 * J01 + J10 * J10 + J11 * J11;

  // Limit-aware escape: identify clipped channel from command vs applied.
  if (n > 0 && h[n - 1].limited && h[n - 1].command) {
