    var dc0 = Math.abs(lc[0] - la[0]), dc1 = Math.abs(lc[1] - la[1]);
    var c = dc0 >= dc1 ? 0 : 1;
    var j = 1 - c;
    var uc = (lc[c] > 0 ? -1 : 1) * lim * 0.5;
    if (lc[c] === 0) uc = 0;
    var Jc0 = c === 0 ? J00 : J01, Jc1 = c === 0 ? J10 : J11;
    var Jj0 = j === 0 ? J00 : J01, Jj1 = j === 0 ? J10 : J11;
    var rx = ex - Jc0 * uc, ry = ey - Jc1 * uc;
    var nj = Jj0 * Jj0 + Jj1 * Jj1;
    var uj;
    if (nj > 1e-9 * (normJ2 + 1e-12) && isFinite(nj)) {
      uj = (rx * Jj0 + ry * Jj1) / nj;
    } else {
      uj = cyc[j === 0 ? 0 : 1];
    }
    if (uj > lim) uj = lim;
    if (uj < -lim) uj = -lim;
