    esc[j] = uj;
    if (!isFinite(esc[0]) || !isFinite(esc[1])) {
      return {action: 'move', u: [cyc[0], cyc[1]]};
    }
    return {action: 'move', u: esc};
  }

  if (!(Math.abs(detJ) > 0.05 * normJ2) || normJ2 <= 0) {
    // Poorly excited or degenerate: keep probing both channels.
    return {action: 'move', u: [cyc[0], cyc[1]]};
  }

  var Ij00 = J11 / detJ, Ij01 = -J01 / detJ, Ij10 = -J10 / detJ, Ij11 = J00 / detJ;
