  var D11 = 0, D12 = 0, D21 = 0, D22 = 0;
  var cnt = 0;
  for (var s = start; s < n; s++) {
    var uu = h[s].applied;
    var dd = h[s].delta;
    if (!uu || !dd || !isFinite(uu[0]) || !isFinite(uu[1]) || !isFinite(dd[0]) || !isFinite(dd[1])) continue;
    if (Math.abs(uu[0]) + Math.abs(uu[1]) < 1e-9) continue;
    cnt++;
    S11 += uu[0] * uu[0];
    S12 += uu[0] * uu[1];
    S22 += uu[1] * uu[1];
    D11 += dd[0] * uu[0];
    D12 += dd[0] * uu[1];
    D21 += dd[1] * uu[0];
    D22 += dd[1] * uu[1];
  }

  var detS = S11 * S22 - S12 * S12;
  if (cnt < 3 || detS < 1e-5) {
    return probe();
  }

  var J11 = (D11 * S22 - D12 * S12) / detS;
  var J12 = (-D11 * S12 + D12 * S11) / detS;
  var J21 = (D21 * S22 - D22 * S12) / detS;
  var J22 = (-D21 * S12 + D22 * S11) / detS;

  if (n >= 1 && h[n - 1].applied && h[n - 1].delta) {
    var ua = h[n - 1].applied;
    var da = h[n - 1].delta;
    var px = J11 * ua[0] + J12 * ua[1];
    var py = J21 * ua[0] + J22 * ua[1];
    var resid = Math.sqrt((px - da[0]) * (px - da[0]) + (py - da[1]) * (py - da[1]));
    var dmag = Math.sqrt(da[0] * da[0] + da[1] * da[1]);
    if (resid > 0.8 * dmag + 6) {
      return probe();
    }
  }

  var detJ = J11 * J22 - J12 * J21;
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-3) {
    return probe();
  }

  var gain = err > 40 ? 1 : 0.5;
  var ux = (J22 * ex - J12 * ey) / detJ * gain;
  var uy = (-J21 * ex + J11 * ey) / detJ * gain;
  if (!isFinite(ux) || !isFinite(uy)) {
    return probe();
  }
  var u = [ux, uy];

  // Blocked channel b: move it away from its limit (retreat), and let the
  // other channel solve the remaining error using the fitted column.
  var bad = [false, false];
  for (var q2 = 0; q2 < 2; q2++) {
    if (blocked[q2] !== 0 && u[q2] !== 0 && ((u[q2] > 0) ? 1 : -1) === blocked[q2]) bad[q2] = true;
  }
  if (bad[0] && bad[1]) {
    var rr = retreatOnly();
    return rr ? rr : probe();
  }
  if (bad[0] || bad[1]) {
    var b = bad[0] ? 0 : 1;
    var o = 1 - b;
    var retB = -blocked[b] * LIM;
    // residual after retreating channel b
    var colB = (b === 0) ? [J11, J21] : [J12, J22];
    var rex = ex - colB[0] * retB;
    var rey = ey - colB[1] * retB;
    var col = (o === 0) ? [J11, J21] : [J12, J22];
    var cc = col[0] * col[0] + col[1] * col[1];
    if (cc < 1e-6) {
      var rr2 = retreatOnly();
      return rr2 ? rr2 : probe();
    }
    var po = (col[0] * rex + col[1] * rey) / cc * gain;
    u[b] = retB;
    u[o] = po;
  }

  var m = Math.max(Math.abs(u[0]), Math.abs(u[1]));
  if (m > LIM) {
    u[0] = u[0] * LIM / m;
    u[1] = u[1] * LIM / m;
  }
  u[0] = Math.max(-LIM, Math.min(LIM, u[0]));
  u[1] = Math.max(-LIM, Math.min(LIM, u[1]));
  if (!isFinite(u[0]) || !isFinite(u[1])) {
    return probe();
  }
  if (pushesBlocked(u)) {
    var rr3 = retreatOnly();
    return rr3 ? rr3 : probe();
  }
  return { action: "move", u: u };
}
